#[cfg(test)]
mod tests {
    use super::*;

    fn pairing() -> MotionPairingState {
        let first = AssetId::generate();
        let second = AssetId::generate();
        MotionPairingState {
            motion_path: Some(PathBuf::from("motion.vmd")),
            original: Some(first.clone()),
            selected: vec![first.clone(), second.clone()],
            candidates: vec![
                (first.clone(), "First".to_owned()),
                (second.clone(), "Second".to_owned()),
            ],
            candidate_paths: vec![
                (first.clone(), PathBuf::from("first.pmx")),
                (second.clone(), PathBuf::from("second.pmx")),
            ],
            humanoid_source: Some(first.clone()),
            humanoid_capable_models: vec![
                (first, "First".to_owned()),
                (second, "Second".to_owned()),
            ],
            retarget_pairs: Vec::new(),
            recorded_model_name: None,
            compatibility_reports: Vec::new(),
        }
    }

    #[test]
    fn target_reordering_does_not_change_humanoid_provenance() {
        let mut state = pairing();
        let source = state.humanoid_source.clone();
        state.selected.reverse();
        assert_eq!(state.humanoid_source, source);
        assert!(motion_humanoid_source_is_valid(&state));
    }

    #[test]
    fn removing_humanoid_source_association_does_not_silently_replace_it() {
        let mut state = pairing();
        let source = state.humanoid_source.clone().expect("source");
        state.selected.retain(|target| target != &source);
        state.original = None;

        assert_eq!(state.humanoid_source, Some(source));
        assert!(!motion_humanoid_source_is_valid(&state));
    }
}
